G=[['拉丁 grex，词干 greg-','一群，尤指一群动物']]
A=G+[['拉丁 ad- + gregare → aggregare；分词 aggregatus','使加入群体、聚到一起'],['英语 aggregate','汇集；总计；集合体']]
C=G+[['拉丁 con- + gregare → congregare；分词 congregatus','聚成一群、集合'],['中古英语 congregate','聚集的；逐渐形成常用动词“聚集”']]
CN=G+[['拉丁 congregare → congregatio／congregationem','聚集 → 集会、聚集的群体'],['古法语 congregacion／拉丁借入 → 中古英语 congregacioun','集会、团体'],['英语 congregation','尤其指共同参加宗教礼拜的会众']]
SE=G+[['拉丁 se-“分开”+ gregare → segregare；分词 segregatus','从群体中分出、隔开'],['英语 segregate','把事物分开；也指实行人群隔离']]
SN=G+[['拉丁 segregare → 晚期拉丁 segregatio／segregationem','隔开 → 隔离、分离的行为'],['英语 segregation','分类隔开；在人群中尤其指种族等隔离']]
DE=SN+[['英语 de-“解除”+ segregation → desegregation','消除人群隔离'],['英语 desegregation 逆构 → desegregate','从名词形成解除隔离的动词；表面也可拆 de- + segregate']]
EG=G+[['拉丁 ex“从……中出来”+ grex → egregius','超出一群的 → 出众、卓越'],['英语 egregious','起初可赞美优秀；反讽、贬义后来成为主流']]
W=[
E('congregation','英 /ˌkɒŋɡrɪˈɡeɪʃən/；美 /ˌkɑːŋɡrɪˈɡeɪʃən/','会众；参加礼拜的群体；集会、聚集的人群','一群人共同来到礼拜场所，听讲、祈祷或参加仪式；也可以指平时属于这个信仰社区的人。','经古法语 congregacion 或直接借拉丁 congregatio／congregationem，来自 congregare“聚成一群”。这个名词在英语里有独立路线，不能只画成现代 congregate 加 -ion。',CN,'the congregation stood up 说会众站起来；a small congregation 既可指这次人数不多，也可能指这个宗教社区成员较少。它重在人群，不是礼拜建筑本身。','a local congregation；members of the congregation；address the congregation。','church 可以指建筑、教会或信仰群体；congregation 更明确强调会众。宗教领导者叫 minister、rabbi 等，取决于具体传统。',('The congregation stood as the music began.','音乐响起时，会众站了起来。'),('Members of the congregation organised meals for their neighbours.','这群会众中的成员为邻居们组织了送餐。'),sources=[S('congregation'),K('congregation'),O('congregation')]),
E('congregational','英 /ˌkɒŋɡrɪˈɡeɪʃənəl/；美 /ˌkɑːŋɡrɪˈɡeɪʃənəl/','会众的；全体会众参与的；〔大写时〕公理会的','把焦点放到一整个礼拜群体上：大家一起唱、共同开会，或共同管理自己的教会。','英语 congregation + -al。小写一般表示与会众有关；大写 Congregational 在教派名称中常指强调地方教会自治的公理会传统。',CN+[['英语 congregation + -al → congregational','与会众相关；教派用法进一步突出地方教会自治']],'congregational singing 是会众一起唱，区别于只有唱诗班表演。a Congregational church 中的大写通常提示教派名称，不能只翻成“人聚在一起的教堂”。','congregational singing；a congregational meeting；Congregational churches。','congregational 是形容词，congregation 是群体名词；不是“祝贺的”，那个词是 congratulatory。',('The service ended with congregational singing.','礼拜在会众合唱中结束。'),('The budget will be discussed at the congregational meeting.','预算将在会众会议上讨论。'),sources=[S('congregational'),K('congregational'),O('congregational')]),
E('congregate','动词英 /ˈkɒŋɡrɪɡeɪt/、美 /ˈkɑːŋɡrɪɡeɪt/；形容词末尾 /ɡət/','聚集；集合；〔形容词〕集中居住或共同使用的','原来分散的个体慢慢来到同一处，形成一群。人群在门口等候，鸟群在树上落脚，都能用。','从拉丁 congregatus“聚在一起的”进入中古英语，来自 con-“一起”+ gregare“聚成群”。早期分词、形容词和后来的动词用法有联系；不是 congregation 的现代缩写。',C,'people congregate outside a café 是人们聚集在咖啡馆外。较正式的 congregate housing、congregate settings 是集中居住或共同活动的环境，形容词末尾常弱读 /ət/。','congregate around；congregate outside；birds congregate；congregate housing。','gather 很日常，也可收集东西；congregate 更有“一群个体来到一处”的感觉，语气较正式。',('Visitors congregated around the guide near the gate.','游客们在大门附近聚到导游身边。'),('Birds congregate on the roof before sunset.','日落前，鸟儿聚集在屋顶上。'),sources=[S('congregate'),K('congregate'),O('congregate')]),
E('congregant','英 /ˈkɒŋɡrɪɡənt/；美 /ˈkɑːŋɡrɪɡənt/','会众中的一员；参加礼拜的成员','congregation 是一整个群体，congregant 是其中一个人。','英语以 congregate 的词干配 -ant，表示参与聚集的人，近代形成。无需把它伪造为直接借来的完整古拉丁名词。',C+[['英语 congregate 词干 + -ant → congregant','聚集者；宗教会众的一名成员']],'a longtime congregant 是长期参加某个宗教社区的人；常见于美国关于教堂、犹太会堂等的报道。它说明参与身份，不自动说明担任神职或具体职务。','a longtime congregant；a fellow congregant；several congregants。','congregation 是群体，congregant 是可数的成员；clergy 是神职人员这个群体，不能一概互换。',('A longtime congregant welcomed the newcomers at the door.','一位长期参加这里礼拜的成员在门口迎接新来的人。'),('Several congregants stayed behind to arrange the chairs.','几位会众留下来整理椅子。'),sources=[K('congregant'),O('congregant'),'https://www.collinsdictionary.com/dictionary/english/congregant']),
E('aggregation','英、美 /ˌæɡrɪˈɡeɪʃən/','汇集；聚集；汇总；聚合形成的整体','把很多小份放到一块儿，再把它们当作一个整体来看，比如把每天的销售额汇成月度数字。','接中世纪拉丁 aggregatio／aggregationem，来自拉丁 aggregare 的词族。与 aggregate 对应，但名词有独立借入来源。',G+[['拉丁 aggregare → 中世纪拉丁 aggregatio／aggregationem','聚到一起 → 汇集、聚合的行为'],['英语 aggregation','汇集过程，也可指形成的整体']],'data aggregation 是数据汇总；aggregation by month 是按月汇总。汇总可能让趋势更清楚，也会把组内差异隐藏起来；它不必一定是相加，也可能采用计数或其他汇总方法。','data aggregation；aggregation by region；the aggregation of results。','aggregation 是合起来看；disaggregation 是拆成更细的组来看。collection 更强调收集，aggregation 更常强调合成整体。',('The dashboard uses monthly aggregation to show long-term trends.','仪表盘按月汇总数据，以展示长期趋势。'),('Aggregation can hide differences between small groups.','汇总可能掩盖小群体之间的差异。'),sources=[S('aggregation'),K('aggregation'),O('aggregation'),'https://unstats.un.org/unsd/classifications/bestpractices/glossary_short.pdf']),
E('aggregator','英 /ˈæɡrɪɡeɪtə/；美 /ˈæɡrɪɡeɪtər/','汇总者；聚合平台；信息聚合工具','不一定亲自生产内容，而是把不同来源的东西收集到同一处，方便你一起查看。','英语 aggregate + -or，表示执行汇集的人或工具。这个名词早于互联网，新闻、价格和订阅聚合平台是后来新场景。',A+[['英语 aggregate + -or → aggregator','汇集者、编集者'],['互联网等现代用法','汇集多来源信息的网站或软件']],'a news aggregator 把不同媒体的新闻集中展示；a price aggregator 汇集不同卖家的价格。聚合本身不保证信息已经核实，也不自动表示平台拥有原内容。','a news aggregator；a price aggregator；a content aggregator；a feed aggregator。','publisher 负责出版、发布内容；aggregator 突出汇集不同来源。一个平台可能兼有两种角色。',('The news aggregator links to articles from several newspapers.','这款新闻聚合工具链接了多家报纸的文章。'),('We used a price aggregator to compare offers from different shops.','我们用价格聚合平台比较了不同商店的报价。'),sources=[S('aggregator'),K('aggregator'),O('aggregator'),'https://www.merriam-webster.com/dictionary/aggregator']),
E('aggregated','英、美 /ˈæɡrɪɡeɪtɪd/','已汇总的；已聚合的','很多单条记录已被放到一起，看到的是合起来的结果，而不是每条原始细节。','英语 aggregate 动词 + -ed；末尾 /t/ 后读 /ɪd/。既是过去式、过去分词，也常作为数据的形容词。',A+[['英语 aggregate + -ed → aggregated','完成汇集；处于汇总后的状态']],'aggregated data 是汇总数据；aggregated by city 是按城市聚合。汇总可能减少细节，但单凭这个词不能保证隐私已经充分保护。','aggregated data；aggregated results；aggregated by month。','aggregate 作形容词可表示总的，aggregated 更显出数据经过了汇总处理。raw data 则强调原始记录。',('The published chart shows aggregated results rather than individual responses.','公布的图表显示的是汇总结果，而非个人回答。'),('The sales figures were aggregated by region.','销售数字按地区进行了汇总。'),sources=[S('aggregate'),K('aggregated'),O('aggregate_3')]),
E('disaggregate','英、美 /dɪsˈæɡrɪɡeɪt/','拆分汇总数据；分解成组成部分','原来看一个总数，现在把它按地区、年龄或产品拆开，看看每一组是什么样。','英语 dis-“反向、分开”+ aggregate。它是在已有汇集动词上形成的反向动作，不是拉丁 disgregate 的现代拼写。',A+[['英语 dis- + aggregate → disaggregate','把合在一起的整体按组成部分拆开']],'disaggregate data by age 是按年龄分组查看数据。若只剩一个总数、原始分组信息已经丢失，不能靠这个动作凭空恢复全部细节。','disaggregate data；disaggregate by region；disaggregate the totals。','aggregate 合并，disaggregate 细分。disintegrate 常指散架、瓦解，通常不是把统计表按类别拆开。',('We need to disaggregate the figures by age group.','我们需要把这些数字按年龄组细分。'),('The report disaggregates national totals into regional results.','报告把全国总数细分成各地区的结果。'),sources=[S('disaggregate'),K('disaggregate'),O('disaggregate'),'https://unstats.un.org/unsd/classifications/bestpractices/glossary_short.pdf']),
E('disaggregation','英、美 /ˌdɪsæɡrɪˈɡeɪʃən/','拆分；细分；汇总数据的分类展开','把“全国一个数字”展开成“每个地区各自的数字”，这个拆开看的过程就是 disaggregation。','英语 disaggregate 对应的 -ion 名词，也可按 dis- + aggregation 看结构。接现代英语构词，不把完整词当作已存在的古拉丁借词。',A+[['英语 disaggregate → disaggregation','拆分汇总整体 → 这种分析过程或结果']],'disaggregation by income 是按收入层次细分；a higher level of disaggregation 是更细的分组。它使群体差异容易看见，但是否能细分取决于原有数据。','data disaggregation；disaggregation by sex；a level of disaggregation。','aggregation 减少细节、看整体；disaggregation 增加分组层次。细分并不必然更准确，样本太小时仍需谨慎解释。',('Disaggregation by region revealed a pattern hidden in the national total.','按地区细分后，全国总数中看不出的趋势显现了出来。'),('The dataset supports disaggregation by both age and income.','这份数据支持按年龄和收入分别细分。'),sources=[S('disaggregate'),K('disaggregation'),'https://www.merriam-webster.com/dictionary/disaggregation','https://unstats.un.org/unsd/classifications/bestpractices/glossary_short.pdf']),
E('segregate','英、美 /ˈseɡrɪɡeɪt/','隔开；分开处理；使人群隔离','把一部分从整体里分出去，让它们不能混在一起。对废物可能是分类处理，对人群则可能涉及排斥和不平等。','接拉丁 segregatus，来自 se-“分开”+ gregare“聚成群”。字面画面是从群体里分出；英语动词以分词词干进入。',SE,'segregate waste 是把不同废物分开；segregate people by race 是按种族隔离人群。单词的社会含义不能只用中性的“分组”带过。','segregate A from B；segregate waste；segregate by race；racially segregate。','separate 是宽泛的分开；segregate 更强调按类别隔开或保持隔离，社会语境常带制度性排斥的含义。',('The facility segregates recyclable material from other waste.','这个设施把可回收材料与其他垃圾分开处理。'),('The exhibition explains how the old system segregated residents by race.','展览解释了旧制度如何按种族隔离居民。'),sources=[S('segregate'),K('segregate'),O('segregate'),'https://www.nps.gov/subjects/segregation/index.htm']),
E('segregation','英、美 /ˌseɡrɪˈɡeɪʃən/','隔离；种族等群体隔离；分离','重点在把某类人与另一类人隔开，并长期保持这种分开；有些场景也只是物品的分类分离。','接晚期拉丁 segregatio／segregationem，来自 segregare 的词族。名词已有独立借入路线，现代虽对应 segregate + -ion，历史不只这一步。',SN,'racial segregation 是种族隔离；segregation in housing 是住房方面的人群隔离。它可以涉及规则、制度，也可以讨论形成的居住格局；具体机制要由上下文说明。','racial segregation；residential segregation；end segregation；segregation in schools。','separation 可以只是分开的位置或动作；segregation 在社会讨论中常指群体被隔开并受到不同对待。',('The museum documents the history of racial segregation.','博物馆记录了种族隔离的历史。'),('The researchers studied residential segregation across the city.','研究人员考察了全市的居住隔离情况。'),sources=[S('segregation'),K('segregation'),O('segregation'),'https://www.nps.gov/subjects/segregation/in-public-education.htm']),
E('segregated','英、美 /ˈseɡrɪɡeɪtɪd/','被隔离的；按类别隔开的','不同群体或物品已经被分开，并维持着分开的安排。','英语 segregate + -ed，/t/ 后读 /ɪd/。既是过去式、过去分词，也常描述隔离后的状态。',SE+[['英语 segregate + -ed → segregated','被分开、被隔离的状态']],'segregated schools 常指实行种族等隔离的学校；segregated waste 指分类存放的废物。看到社会主题时，要保留隔离制度与区别对待的意味。','racially segregated；segregated schools；segregated housing；segregated waste。','secluded 是僻静、与外界隔开的地方；segregated 通常涉及按群体或类别分开，不等于环境安静。',('The archive includes photographs of segregated classrooms.','档案中收录了实行隔离的教室照片。'),('The containers keep different types of waste segregated.','这些容器让不同种类的废物保持分开。'),sources=[K('segregated'),S('segregate'),O('segregated'),'https://www.nps.gov/subjects/segregation/places.htm']),
E('segregationist','英、美 /ˌseɡrɪˈɡeɪʃənɪst/','种族隔离主义者；主张群体隔离的；隔离主义的','不是被隔离的人，而是支持、维护这种人群隔离政策的人或立场。','英语 segregation + -ist，-ist 表示支持某种主张的人；也可转作形容词说明隔离主义立场。',SN+[['英语 segregation + -ist → segregationist','支持隔离制度的人；持这种立场的']],'a segregationist politician 是支持隔离制度的政治人物；segregationist policies 是相关政策。常见于历史、政治新闻，语义比“喜欢分组的人”严肃具体得多。','a segregationist politician；segregationist policies；oppose segregationists。','segregated 说被隔离的状态；segregationist 说支持隔离的立场或人。受害者与支持者不能混为一谈。',('The documentary examines the arguments used by segregationist politicians.','纪录片考察了支持隔离制度的政治人物所使用的说辞。'),('Civil rights activists challenged the segregationists at public meetings.','民权活动人士在公开会议上质疑隔离主义者的主张。'),sources=[K('segregationist'),'https://dictionary.cambridge.org/dictionary/english/segregationist?topic=political-movements-and-groups','https://www.nps.gov/subjects/segregation/places.htm']),
E('desegregation','英、美 /ˌdiːseɡrɪˈɡeɪʃən/','取消种族隔离；解除人群隔离','原来被制度或安排隔开的群体，开始能够共同使用学校、设施或空间；重点是拆掉隔离安排。','英语 de-“解除”+ segregation，20 世纪形成，尤其用于美国种族隔离问题。名词记录早于 desegregate 的常见记录，动词的一条重要来源是由名词逆构。',SN+[['英语 de- + segregation → desegregation','消除已有的群体隔离安排']],'school desegregation 是学校取消隔离。制度上的取消与现实中完全平等并不等同，所以文章可能同时讨论已经推行的 desegregation 和仍然存在的差距。','school desegregation；a desegregation plan；the struggle for desegregation。','segregation 是隔开，desegregation 是解除隔离；integration 还常强调进入共同生活、形成较充分融合的过程。',('The book follows several families during school desegregation.','这本书追踪了学校取消隔离期间几个家庭的经历。'),('The exhibition shows both support for and resistance to desegregation.','展览展示了取消隔离过程中出现的支持与阻力。'),sources=[S('desegregation'),K('desegregation'),O('desegregation'),'https://www.nps.gov/subjects/segregation/in-public-education.htm']),
E('desegregate','英、美 /ˌdiːˈseɡrɪɡeɪt/','取消……的种族隔离；使解除隔离','把原来规定不同人群分开使用的学校或设施，改成不再实行这种隔离。','现代容易看作 de- + segregate；词源资料也明确记为从较早的 desegregation 逆构。历史链先保留名词，再到动词，避免把现代可拆结构误当唯一先后顺序。',DE,'desegregate a school 是取消学校的隔离安排，不是把学校拆成几个部分。这个动词常用于历史报道、制度变化与社会运动的叙述。','desegregate schools；desegregate public facilities；a campaign to desegregate。','disaggregate 是拆分数据或整体，desegregate 是解除人群隔离。两者都有分合意象，但动作方向和使用场景很不同。',('The campaign sought to desegregate the town’s public facilities.','这场运动寻求取消镇上公共设施的隔离制度。'),('The chapter describes efforts to desegregate local schools.','这一章描述了为取消当地学校隔离所作的努力。'),sources=[S('desegregate'),K('desegregate'),O('desegregate'),'https://www.nps.gov/subjects/segregation/in-public-education.htm']),
E('gregarious','英 /ɡrɪˈɡeəriəs/；美 /ɡrɪˈɡeriəs/','爱交际的；喜欢与人相处的；群居的','比起一个人待着，更喜欢在人群里说话、活动；用于动物则是常常结群生活。','借拉丁 gregarius“属于群体、成群的”，来自 grex／greg-。英语采用 -ous 形容词形式；不是把一个现代英语 gregar 当作常用基础词。',G+[['拉丁 gregarius → 英语 gregarious','成群的；后来也指喜欢社交、与人相处']],'a gregarious host 会主动和客人聊天；gregarious birds 是群居鸟类。爱交际不等于总有领导欲，也不保证永远喜欢热闹。','a gregarious person；naturally gregarious；gregarious animals。','sociable 与人的 gregarious 很接近；outgoing 偏外向主动。动物的群居可以 gregarious，通常不把它解释成会聊天。',('Her gregarious brother soon knew everyone at the party.','她那位爱交际的哥哥很快就认识了聚会上的每个人。'),('These birds are gregarious and often feed in groups.','这些鸟喜欢群居，经常成群觅食。'),sources=[S('gregarious'),K('gregarious'),O('gregarious')]),
E('egregious','英、美 /ɪˈɡriːdʒəs/','极其严重的；坏得出格的；明显恶劣的','错误或行为坏得特别突出，让人一眼就觉得“这也太离谱了”。','接拉丁 egregius，本来是从群体里突出、出众优秀：e- 接 ex-“向外”，greg- 是群。英语早期也可赞美，后来反讽用法发展，现代以强烈贬义为主。',EG,'an egregious error 是严重得很突出的错误；egregious misconduct 是明显恶劣的不当行为。不要用它夸一个人的优秀表现，除非明确讨论古义。','an egregious error；egregious misconduct；an egregious example；particularly egregious。','outstanding 今天仍常赞美优秀，egregious 今天通常批评恶劣。两者都能联想到突出，但语义方向不同。',('The review identified an egregious error in the calculation.','审查发现计算中有一个极其严重的错误。'),('The article describes an egregious misuse of public resources.','文章描述了一起严重滥用公共资源的事件。'),sources=[S('egregious'),K('egregious'),O('egregious')]),
E('egregiously','英、美 /ɪˈɡriːdʒəsli/','极其恶劣地；严重得出格地；明显离谱地','用来加强批评：不只是错了，而是错得格外突出、令人难以接受。','英语 egregious + -ly，承接现代强烈贬义，而不是拉丁时代的优秀赞美。',EG+[['英语 egregious + -ly → egregiously','以严重、出格的方式；用来加强负面评价']],'egregiously wrong 是错得离谱；egregiously misleading 是严重误导。它修饰形容词或动作时，都比一般 very、badly 更带强烈评价。','egregiously wrong；egregiously misleading；behave egregiously。','especially 可以中性说尤其；egregiously 一般只强化负面评价，不说 egregiously talented 来正常赞美天赋。',('The headline was egregiously misleading.','这个标题具有严重的误导性。'),('The estimate was not merely optimistic; it was egregiously wrong.','这个估计不只是乐观，而是错得离谱。'),sources=[K('egregiously'),O('egregiously'),S('egregious')]),
]
SHARED=['aggregate']
EX={w:'古旧形式或专门生物学、跨会众术语，按用户常用阅读优先要求暂略。' for w in ['disgregate','disgregation','gregarian','gregarine','intercongregational']}
ROOT=dict(id='C0505',meaning='一群；聚在一起',core='拉丁 grex、词干 greg- 是一群。往群里放，是聚集；从群里分出，是隔离；偏爱待在人群里，是爱交际。',image='聚成一群 → congregate；汇成整体 → aggregate；群体里的人 → congregation；分出群体 → segregate；解除隔离 → desegregate；喜欢结群 → gregarious；突出群体 → egregious，现代多指坏得突出。',intro='这个根在数据分析、宗教群体、社会历史和人物描写中都很有用。用“群”联系它们，但具体语气必须单独记：egregious 已经主要是贬义，segregation 在社会语境里也远不止普通分组。',forms='grex 的屈折词干 greg- 进入 gregare“聚成一群”。ad- 在 aggregate 中同化为 ag-，con- 表一起，se- 表分开。congregation、aggregation、segregation 各自有拉丁名词借入路线；desegregate 则有从 desegregation 逆构的历史，不要只按今天能拆出的片段猜先后。',branches=[['汇总与细分','aggregate, aggregated, aggregation, aggregator, disaggregate, disaggregation'],['聚集与会众','congregate, congregation, congregational, congregant'],['隔离与解除隔离','segregate, segregation, segregated, segregationist, desegregation, desegregate'],['喜欢群体与突出群体','gregarious, egregious, egregiously']],contrasts='aggregate 把各项合起来看，disaggregate 把整体细分。congregation 是会众，congregant 是其中一员。segregated 是被隔离的，segregationist 是支持隔离的。gregarious 常为中性或正面，egregious 在现代通常负面。',practice='An aggregator gathers items together; a gregarious person enjoys gathering with people. 聚合工具把项目汇到一起，爱交际的人喜欢和人们聚在一起。',words=[],exclude=EX)
